-- Prisma baseline for an existing SocietyBooks database.
--
-- GENERATED by scripts/build-prisma-baseline.mjs from server/migrations/*.sql.
-- Do not edit: run that script instead, with --verify, which applies this file
-- to an empty database and diffs the result against a database the migration
-- runner built. The two match, or the script fails.
--
-- WHAT IT IS NOT: a migration to run by hand, and not a licence to use
-- `prisma migrate dev`. Prisma cannot express the deferred constraint
-- triggers that make an unbalanced journal entry impossible to commit, the
-- trigger that refuses a posting into a closed period, the control-party rule,
-- the DO INSTEAD NOTHING delete rules, or the partial unique indexes. A schema
-- Prisma created from its own schema file would be missing every one of them,
-- which is why the SQL migrations remain the migration path.
--
-- AGAINST A DATABASE THAT ALREADY HAS THE SCHEMA:
--
--   npx prisma migrate resolve --applied 0_init
--
-- records this as applied without executing it, so `prisma migrate status` is
-- clean. Then `prisma db pull` to refresh prisma/schema.prisma from the
-- database, and `prisma generate` for the typed client.
--
-- AGAINST AN EMPTY DATABASE: prefer `node server/migrate.mjs`. It records each
-- file with its checksum and refuses to continue if one that was already
-- applied has since changed. This file ends by recording the same rows, so a
-- database created from it is consistent with the runner too.
--
-- Covers: 001_initial.sql, 002_balance_guard.sql, 003_domain.sql, 004_fix_allocation_guard.sql, 005_login_identity.sql, 006_gst_register_notes.sql, 007_canonical_billing_period.sql, 008_security_hardening.sql, 009_bank_match_once.sql, 010_opening_balances.sql

-- ====================================================================
-- 001_initial.sql
-- ====================================================================

-- SocietyBooks schema, migration 001.
--
-- The invariants the engine enforces in TypeScript are enforced here as well.
-- Two reasons: a second writer that bypasses the application cannot corrupt
-- the books, and a constraint violation is caught by the database inside the
-- transaction rather than after a partial write.
--
-- Money is stored as BIGINT paise, never NUMERIC or DOUBLE. The engine works
-- in integer paise for the same reason: no two-decimal value is lost, and a
-- trial balance compares exactly.

BEGIN;

CREATE TABLE schema_migrations (
  version      TEXT PRIMARY KEY,
  applied_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  checksum     TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- Societies. Multi-tenant from the start: retrofitting a tenant column onto
-- a ledger means rewriting every row and every query.
-- --------------------------------------------------------------------------
CREATE TABLE societies (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name          TEXT NOT NULL,
  -- 'demo' rows hold sample data. Kept in the same schema so the separation is
  -- a column that every query filters on, rather than two deployments that
  -- drift apart.
  mode          TEXT NOT NULL CHECK (mode IN ('demo', 'production')),
  registration_no TEXT,
  gstin         TEXT,
  state_code    TEXT,
  financial_year_start_month SMALLINT NOT NULL DEFAULT 4
                CHECK (financial_year_start_month BETWEEN 1 AND 12),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON COLUMN societies.gstin IS
  'Left null until the association supplies its own. Never populated with a sample value: a GSTIN on a tax invoice is a legal assertion.';

-- --------------------------------------------------------------------------
-- Chart of accounts
-- --------------------------------------------------------------------------
CREATE TABLE accounts (
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  code          TEXT NOT NULL,
  name          TEXT NOT NULL,
  class         TEXT NOT NULL CHECK (class IN ('asset','liability','fund','income','expenditure')),
  grp           TEXT NOT NULL,
  is_cash       BOOLEAN NOT NULL DEFAULT false,
  control       TEXT CHECK (control IN ('resident','vendor')),
  PRIMARY KEY (society_id, code)
);

-- --------------------------------------------------------------------------
-- Flats and the people who own them
-- --------------------------------------------------------------------------
CREATE TABLE flats (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  flat_no         TEXT NOT NULL,
  wing            TEXT,
  floor           SMALLINT,
  billing_area_sqft NUMERIC(10,2) CHECK (billing_area_sqft IS NULL OR billing_area_sqft > 0),
  -- Nullable on purpose. A flat with no recorded basis cannot be billed, and
  -- the application refuses rather than assuming one: the same rate over
  -- carpet and over super built-up area differs by roughly a third.
  area_basis      TEXT CHECK (area_basis IN ('carpet','built-up','super-built-up')),
  non_occupied    BOOLEAN NOT NULL DEFAULT false,
  UNIQUE (society_id, flat_no)
);

CREATE TABLE owners (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  full_name     TEXT NOT NULL,
  email         TEXT NOT NULL,
  phone         TEXT,
  pan           TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (society_id, email)
);

-- An owner may hold more than one flat, and a flat may change hands, so the
-- mapping is its own table with dates rather than a column on either side.
CREATE TABLE flat_ownership (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  flat_id       UUID NOT NULL REFERENCES flats(id) ON DELETE RESTRICT,
  owner_id      UUID NOT NULL REFERENCES owners(id) ON DELETE RESTRICT,
  role          TEXT NOT NULL CHECK (role IN ('owner','co-owner','tenant')),
  held_from     DATE NOT NULL,
  held_until    DATE,
  CHECK (held_until IS NULL OR held_until >= held_from)
);

-- One current owner per flat per role, enforced rather than hoped for: two
-- open ownership rows is how old dues attach to a new owner.
CREATE UNIQUE INDEX flat_ownership_one_current
  ON flat_ownership (flat_id, role)
  WHERE held_until IS NULL;

CREATE INDEX flat_ownership_by_owner ON flat_ownership (owner_id);

-- --------------------------------------------------------------------------
-- Users, roles, sessions
-- --------------------------------------------------------------------------
CREATE TABLE users (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  email           TEXT NOT NULL,
  -- A hash and its parameters. Never a PIN, and never anything reversible.
  password_hash   TEXT,
  owner_id        UUID REFERENCES owners(id) ON DELETE RESTRICT,
  is_active       BOOLEAN NOT NULL DEFAULT true,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_login_at   TIMESTAMPTZ,
  UNIQUE (society_id, email)
);

COMMENT ON COLUMN users.password_hash IS
  'Null for an account that signs in by emailed one-time code only. The demo PIN mechanism has no column here: it is a demo-mode-only path in the application and cannot authorise anything in production mode.';

CREATE TABLE user_roles (
  user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role      TEXT NOT NULL CHECK (role IN ('resident','manager','treasurer','secretary','auditor')),
  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  granted_by UUID REFERENCES users(id),
  PRIMARY KEY (user_id, role)
);

CREATE TABLE sessions (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- The token is stored hashed, so a database copy does not hand over live
  -- sessions.
  token_hash    TEXT NOT NULL UNIQUE,
  issued_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at    TIMESTAMPTZ NOT NULL,
  revoked_at    TIMESTAMPTZ,
  user_agent    TEXT,
  CHECK (expires_at > issued_at)
);

CREATE INDEX sessions_by_user ON sessions (user_id) WHERE revoked_at IS NULL;

CREATE TABLE login_codes (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- Hashed, so the code cannot be read out of the database and used. The demo
  -- showed the code on screen; that is a demo-mode behaviour and this column
  -- deliberately cannot support it.
  code_hash     TEXT NOT NULL,
  issued_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at    TIMESTAMPTZ NOT NULL,
  consumed_at   TIMESTAMPTZ,
  attempts      SMALLINT NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  CHECK (expires_at > issued_at)
);

CREATE INDEX login_codes_live ON login_codes (user_id, expires_at) WHERE consumed_at IS NULL;

-- --------------------------------------------------------------------------
-- The ledger
-- --------------------------------------------------------------------------
CREATE TABLE journal_entries (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id        UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  -- The application's own reference, kept so a restored snapshot and the
  -- database agree on entry identity.
  entry_ref         TEXT NOT NULL,
  entry_date        DATE NOT NULL,
  narration         TEXT NOT NULL CHECK (length(btrim(narration)) > 0),
  source_kind       TEXT NOT NULL,
  source_ref        TEXT,
  -- The duplicate guard, at the database. Two concurrent requests for the same
  -- business event cannot both succeed: the second violates this and its
  -- transaction rolls back whole.
  idempotency_key   TEXT NOT NULL,
  reversal_of       UUID REFERENCES journal_entries(id),
  reversed_by       UUID REFERENCES journal_entries(id),
  posted_by         UUID REFERENCES users(id),
  posted_by_label   TEXT NOT NULL,
  posted_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- Denormalised so the balance constraint can be deferred to statement end
  -- and checked without re-aggregating the legs.
  total_debit       BIGINT NOT NULL CHECK (total_debit > 0),
  total_credit      BIGINT NOT NULL CHECK (total_credit > 0),
  CONSTRAINT journal_entry_balances CHECK (total_debit = total_credit),
  UNIQUE (society_id, idempotency_key),
  UNIQUE (society_id, entry_ref)
);

CREATE INDEX journal_entries_by_date ON journal_entries (society_id, entry_date);
CREATE INDEX journal_entries_by_source ON journal_entries (society_id, source_kind, source_ref);

-- An entry is never deleted. A correction is a reversal, and this makes that
-- the only possibility rather than a convention.
CREATE RULE journal_entries_no_delete AS ON DELETE TO journal_entries DO INSTEAD NOTHING;

CREATE TABLE journal_postings (
  id            BIGSERIAL PRIMARY KEY,
  entry_id      UUID NOT NULL REFERENCES journal_entries(id) ON DELETE RESTRICT,
  society_id    UUID NOT NULL,
  account_code  TEXT NOT NULL,
  debit         BIGINT NOT NULL DEFAULT 0 CHECK (debit >= 0),
  credit        BIGINT NOT NULL DEFAULT 0 CHECK (credit >= 0),
  -- Exactly one side, as in the engine. A leg carrying both is how a posting
  -- that looks balanced hides a second movement.
  CONSTRAINT posting_one_side CHECK ((debit = 0) <> (credit = 0)),
  party         TEXT,
  doc_ref       TEXT,
  memo          TEXT,
  FOREIGN KEY (society_id, account_code) REFERENCES accounts(society_id, code)
);

CREATE INDEX journal_postings_by_entry ON journal_postings (entry_id);
CREATE INDEX journal_postings_by_account ON journal_postings (society_id, account_code);
CREATE INDEX journal_postings_by_party ON journal_postings (society_id, account_code, party)
  WHERE party IS NOT NULL;
CREATE INDEX journal_postings_by_doc ON journal_postings (society_id, account_code, doc_ref)
  WHERE doc_ref IS NOT NULL;

CREATE RULE journal_postings_no_delete AS ON DELETE TO journal_postings DO INSTEAD NOTHING;

-- --------------------------------------------------------------------------
-- The billing register
-- --------------------------------------------------------------------------
CREATE TABLE billing_documents (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id        UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  proforma_no       TEXT NOT NULL,
  tax_invoice_no    TEXT,
  flat_id           UUID NOT NULL REFERENCES flats(id) ON DELETE RESTRICT,
  period            TEXT NOT NULL,
  estimated_tax     BIGINT NOT NULL CHECK (estimated_tax >= 0),
  gross             BIGINT NOT NULL CHECK (gross > 0),
  issued_on         DATE NOT NULL,
  due_on            DATE NOT NULL,
  state             TEXT NOT NULL CHECK (state IN ('draft','approved','released','tax-invoice','cancelled')),
  approved_by       UUID REFERENCES users(id),
  approved_on       DATE,
  converted_on      DATE,
  converted_because TEXT CHECK (converted_because IN ('payment-received','due-date-reached','manual')),
  posted_entry_id   UUID REFERENCES journal_entries(id),
  cancelled_by      UUID REFERENCES users(id),
  cancelled_reason  TEXT,
  UNIQUE (society_id, proforma_no),
  UNIQUE (society_id, tax_invoice_no),
  CHECK (due_on >= issued_on),
  CHECK (approved_on IS NULL OR approved_on >= issued_on),
  CHECK (converted_on IS NULL OR converted_on >= issued_on),
  -- A document past draft must name who approved it, and a cancellation must
  -- give a reason. Both were enforced only in the application before.
  CHECK (state = 'draft' OR state = 'cancelled' OR approved_by IS NOT NULL),
  CHECK (state <> 'cancelled' OR cancelled_reason IS NOT NULL),
  CHECK (state <> 'tax-invoice' OR (tax_invoice_no IS NOT NULL AND posted_entry_id IS NOT NULL))
);

-- The duplicate-billing guard. A partial unique index, so a cancelled document
-- frees the flat and period for a replacement while a live one does not.
CREATE UNIQUE INDEX billing_documents_one_live_per_period
  ON billing_documents (society_id, flat_id, period)
  WHERE state <> 'cancelled';

CREATE TABLE billing_document_lines (
  id            BIGSERIAL PRIMARY KEY,
  document_id   UUID NOT NULL REFERENCES billing_documents(id) ON DELETE CASCADE,
  head          TEXT NOT NULL CHECK (head IN ('maintenance','sinking','festival','rental','reimbursement','other')),
  amount        BIGINT NOT NULL CHECK (amount > 0),
  taxable       BOOLEAN NOT NULL,
  position      SMALLINT NOT NULL,
  UNIQUE (document_id, position)
);

CREATE TABLE dispatch_attempts (
  id            BIGSERIAL PRIMARY KEY,
  document_id   UUID NOT NULL REFERENCES billing_documents(id) ON DELETE CASCADE,
  attempted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  by_user       UUID REFERENCES users(id),
  channel       TEXT NOT NULL,
  -- False until a provider confirms. A row recording a delivery that did not
  -- happen is worse than no row: a committee acts on it.
  delivered     BOOLEAN NOT NULL DEFAULT false,
  provider_id   TEXT,
  failure       TEXT,
  note          TEXT NOT NULL
);

CREATE INDEX dispatch_attempts_undelivered
  ON dispatch_attempts (document_id) WHERE delivered = false;

-- --------------------------------------------------------------------------
-- Rates, with dates
-- --------------------------------------------------------------------------
CREATE TABLE maintenance_rates (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  rate_paise_per_sqft BIGINT NOT NULL CHECK (rate_paise_per_sqft > 0),
  area_basis      TEXT NOT NULL CHECK (area_basis IN ('carpet','built-up','super-built-up')),
  effective_from  DATE NOT NULL,
  authority       TEXT NOT NULL,
  -- A rate cannot bill until someone signs it off. Null here is what makes
  -- the application refuse.
  approved_by     UUID REFERENCES users(id),
  approved_on     DATE,
  UNIQUE (society_id, effective_from)
);

-- --------------------------------------------------------------------------
-- Audit log
-- --------------------------------------------------------------------------
CREATE TABLE audit_log (
  id            BIGSERIAL PRIMARY KEY,
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_user    UUID REFERENCES users(id),
  actor_label   TEXT NOT NULL,
  action        TEXT NOT NULL,
  subject_table TEXT,
  subject_id    TEXT,
  -- What changed, as JSON. Append-only.
  detail        JSONB,
  request_id    TEXT
);

CREATE INDEX audit_log_by_time ON audit_log (society_id, at DESC);
CREATE INDEX audit_log_by_subject ON audit_log (society_id, subject_table, subject_id);

CREATE RULE audit_log_no_delete AS ON DELETE TO audit_log DO INSTEAD NOTHING;
CREATE RULE audit_log_no_update AS ON UPDATE TO audit_log DO INSTEAD NOTHING;

COMMIT;


-- ====================================================================
-- 002_balance_guard.sql
-- ====================================================================

-- Migration 002: make the balance invariant impossible to break.
--
-- Migration 001 stores each entry's totals and constrains them equal, but
-- nothing yet ties those totals to the legs. A writer could insert an entry
-- claiming 10,000 on each side and then post legs that sum to something else.
-- A deferred constraint trigger closes that: it fires at COMMIT, so the legs
-- may be inserted in any order within the transaction, and the whole
-- transaction fails if the sums disagree.

BEGIN;

CREATE OR REPLACE FUNCTION check_entry_balances() RETURNS TRIGGER AS $$
DECLARE
  entry UUID;
  leg_debit BIGINT;
  leg_credit BIGINT;
  stated_debit BIGINT;
  stated_credit BIGINT;
  leg_count INT;
BEGIN
  entry := COALESCE(NEW.entry_id, OLD.entry_id);

  SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0), COUNT(*)
    INTO leg_debit, leg_credit, leg_count
    FROM journal_postings WHERE entry_id = entry;

  SELECT total_debit, total_credit INTO stated_debit, stated_credit
    FROM journal_entries WHERE id = entry;

  IF stated_debit IS NULL THEN
    RAISE EXCEPTION 'posting references entry % which does not exist', entry;
  END IF;

  IF leg_count < 2 THEN
    RAISE EXCEPTION
      'entry % has % leg(s); a double-entry transaction needs at least two',
      entry, leg_count;
  END IF;

  IF leg_debit <> leg_credit THEN
    RAISE EXCEPTION
      'entry % does not balance: legs total % debit against % credit (out by %)',
      entry, leg_debit, leg_credit, leg_debit - leg_credit;
  END IF;

  IF leg_debit <> stated_debit OR leg_credit <> stated_credit THEN
    RAISE EXCEPTION
      'entry % states %/% but its legs total %/%',
      entry, stated_debit, stated_credit, leg_debit, leg_credit;
  END IF;

  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- DEFERRABLE INITIALLY DEFERRED: checked once at COMMIT rather than after each
-- row, which is the only way a multi-leg entry can be inserted at all.
CREATE CONSTRAINT TRIGGER journal_postings_balance
  AFTER INSERT OR UPDATE ON journal_postings
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_entry_balances();

-- An entry with no legs at all would otherwise pass, since the trigger above
-- only fires on a posting. This one fires on the entry.
CREATE OR REPLACE FUNCTION check_entry_has_legs() RETURNS TRIGGER AS $$
DECLARE
  leg_count INT;
BEGIN
  SELECT COUNT(*) INTO leg_count FROM journal_postings WHERE entry_id = NEW.id;
  IF leg_count < 2 THEN
    RAISE EXCEPTION
      'entry % was committed with % leg(s); at least two are required',
      NEW.id, leg_count;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER journal_entries_have_legs
  AFTER INSERT ON journal_entries
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_entry_has_legs();

-- A control account's legs must name a party, as in the engine. Without it a
-- receivable balance cannot be attributed to a flat.
CREATE OR REPLACE FUNCTION check_control_party() RETURNS TRIGGER AS $$
DECLARE
  needs TEXT;
BEGIN
  SELECT control INTO needs FROM accounts
   WHERE society_id = NEW.society_id AND code = NEW.account_code;
  IF needs IS NOT NULL AND (NEW.party IS NULL OR btrim(NEW.party) = '') THEN
    RAISE EXCEPTION
      'account % is a % control account, so the posting must name a party',
      NEW.account_code, needs;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER journal_postings_control_party
  BEFORE INSERT OR UPDATE ON journal_postings
  FOR EACH ROW EXECUTE FUNCTION check_control_party();

COMMIT;


-- ====================================================================
-- 003_domain.sql
-- ====================================================================

-- Migration 003: the rest of the domain.
--
-- Banking and reconciliation, the six receipt heads as first-class rows,
-- sinking funds and deposits, events, vendor contracts, GST and TDS registers,
-- helpdesk, document generation, notification delivery, committee approvals,
-- scheduled jobs and financial period locks.
--
-- Same rules as 001 and 002: money is BIGINT paise, every table carries
-- society_id, nothing financial can be deleted, and no column exists that
-- could hold a credential the system should never see.

BEGIN;

-- --------------------------------------------------------------------------
-- Society configuration, as versioned rows rather than columns
-- --------------------------------------------------------------------------
CREATE TABLE society_settings (
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  key           TEXT NOT NULL,
  value         JSONB NOT NULL,
  -- Who confirmed it, for the settings that are accounting or tax treatments.
  -- Null means nobody has, and the application refuses to rely on it.
  approved_by   UUID REFERENCES users(id),
  approved_on   DATE,
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  note          TEXT,
  PRIMARY KEY (society_id, key)
);

COMMENT ON COLUMN society_settings.approved_by IS
  'Null for any setting a CA has not signed off. The billing path refuses to use an unapproved tax treatment rather than defaulting to one.';

-- --------------------------------------------------------------------------
-- Towers
-- --------------------------------------------------------------------------
CREATE TABLE towers (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  name          TEXT NOT NULL,
  floors        SMALLINT CHECK (floors IS NULL OR floors > 0),
  UNIQUE (society_id, name)
);

ALTER TABLE flats ADD COLUMN tower_id UUID REFERENCES towers(id);

-- --------------------------------------------------------------------------
-- The six receipt heads, as rows
-- --------------------------------------------------------------------------
CREATE TABLE receipt_heads (
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  key             TEXT NOT NULL CHECK (key IN
                   ('maintenance','sinking','festival','rental','reimbursement','other')),
  label           TEXT NOT NULL,
  -- Where a collection under this head is credited.
  income_account  TEXT,
  fund_account    TEXT,
  taxable         BOOLEAN NOT NULL,
  -- True where a contribution credits the fund directly instead of income.
  credits_fund_directly BOOLEAN NOT NULL DEFAULT false,
  PRIMARY KEY (society_id, key),
  FOREIGN KEY (society_id, income_account) REFERENCES accounts(society_id, code),
  FOREIGN KEY (society_id, fund_account) REFERENCES accounts(society_id, code),
  -- A head must credit something.
  CHECK (income_account IS NOT NULL OR fund_account IS NOT NULL),
  -- And a head that credits the fund directly must name that fund.
  CHECK (NOT credits_fund_directly OR fund_account IS NOT NULL)
);

-- --------------------------------------------------------------------------
-- Invoice adjustments: credit and debit notes
-- --------------------------------------------------------------------------
CREATE TABLE invoice_adjustments (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  document_id   UUID NOT NULL REFERENCES billing_documents(id) ON DELETE RESTRICT,
  note_no       TEXT NOT NULL,
  kind          TEXT NOT NULL CHECK (kind IN ('credit','debit')),
  reason        TEXT NOT NULL CHECK (length(btrim(reason)) > 0),
  amount        BIGINT NOT NULL CHECK (amount > 0),
  tax_amount    BIGINT NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
  issued_on     DATE NOT NULL,
  approved_by   UUID REFERENCES users(id),
  posted_entry_id UUID REFERENCES journal_entries(id),
  UNIQUE (society_id, note_no),
  -- An adjustment that has been posted must say who approved it.
  CHECK (posted_entry_id IS NULL OR approved_by IS NOT NULL)
);

CREATE RULE invoice_adjustments_no_delete AS ON DELETE TO invoice_adjustments DO INSTEAD NOTHING;

-- --------------------------------------------------------------------------
-- Payments and receipt allocations
-- --------------------------------------------------------------------------
CREATE TABLE payments (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  receipt_no      TEXT NOT NULL,
  flat_id         UUID NOT NULL REFERENCES flats(id) ON DELETE RESTRICT,
  received_on     DATE NOT NULL,
  amount          BIGINT NOT NULL CHECK (amount > 0),
  method          TEXT NOT NULL,
  instrument_ref  TEXT,
  bank_account_id UUID,
  posted_entry_id UUID REFERENCES journal_entries(id),
  -- The caller's key, so a retried request cannot take the money twice.
  idempotency_key TEXT NOT NULL,
  recorded_by     UUID REFERENCES users(id),
  recorded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (society_id, receipt_no),
  UNIQUE (society_id, idempotency_key)
);

CREATE RULE payments_no_delete AS ON DELETE TO payments DO INSTEAD NOTHING;

-- Which document each slice of a receipt settled. The sum of a payment's
-- allocations plus what it holds as advance equals the payment.
CREATE TABLE receipt_allocations (
  id            BIGSERIAL PRIMARY KEY,
  payment_id    UUID NOT NULL REFERENCES payments(id) ON DELETE RESTRICT,
  document_id   UUID REFERENCES billing_documents(id) ON DELETE RESTRICT,
  -- Null document means the slice was held on account as an advance.
  amount        BIGINT NOT NULL CHECK (amount > 0),
  head          TEXT CHECK (head IN
                 ('maintenance','sinking','festival','rental','reimbursement','other')),
  allocated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX receipt_allocations_by_payment ON receipt_allocations (payment_id);
CREATE INDEX receipt_allocations_by_document ON receipt_allocations (document_id);
CREATE RULE receipt_allocations_no_delete AS ON DELETE TO receipt_allocations DO INSTEAD NOTHING;

-- A payment's allocations must add up to the payment, checked at commit so the
-- rows can be inserted in any order.
CREATE OR REPLACE FUNCTION check_payment_allocated() RETURNS TRIGGER AS $$
DECLARE
  pid UUID;
  allocated BIGINT;
  received BIGINT;
BEGIN
  pid := COALESCE(NEW.payment_id, OLD.payment_id);
  SELECT COALESCE(SUM(amount), 0) INTO allocated
    FROM receipt_allocations WHERE payment_id = pid;
  SELECT amount INTO received FROM payments WHERE id = pid;
  IF received IS NULL THEN
    RAISE EXCEPTION 'allocation references payment % which does not exist', pid;
  END IF;
  IF allocated <> received THEN
    RAISE EXCEPTION
      'payment % received % but its allocations total % (out by %)',
      pid, received, allocated, allocated - received;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER receipt_allocations_cover_payment
  AFTER INSERT OR UPDATE ON receipt_allocations
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_payment_allocated();

CREATE CONSTRAINT TRIGGER payments_are_allocated
  AFTER INSERT ON payments
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_payment_allocated();

-- --------------------------------------------------------------------------
-- Sinking fund and fixed deposits
-- --------------------------------------------------------------------------
CREATE TABLE fixed_deposits (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  fd_ref          TEXT NOT NULL,
  bank_name       TEXT NOT NULL,
  -- Last four digits only. The full number is not needed to run a register and
  -- is one more thing to lose.
  account_last4   TEXT CHECK (account_last4 IS NULL OR account_last4 ~ '^[0-9]{4}$'),
  principal       BIGINT NOT NULL CHECK (principal > 0),
  rate_bps        INTEGER NOT NULL CHECK (rate_bps > 0),
  placed_on       DATE NOT NULL,
  matures_on      DATE NOT NULL,
  closed_on       DATE,
  interest_accrued BIGINT NOT NULL DEFAULT 0 CHECK (interest_accrued >= 0),
  fund            TEXT NOT NULL CHECK (fund IN ('sinking','festival','general')),
  UNIQUE (society_id, fd_ref),
  CHECK (matures_on > placed_on),
  CHECK (closed_on IS NULL OR closed_on >= placed_on)
);

COMMENT ON COLUMN fixed_deposits.rate_bps IS
  'Basis points, so 7.25% is 725 and no fractional rate is stored as a float.';

-- --------------------------------------------------------------------------
-- Events
-- --------------------------------------------------------------------------
CREATE TABLE events (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  name          TEXT NOT NULL,
  held_on       DATE,
  budget        BIGINT CHECK (budget IS NULL OR budget >= 0),
  -- Voluntary collections are not dues; billing never raises them.
  voluntary     BOOLEAN NOT NULL DEFAULT true,
  closed        BOOLEAN NOT NULL DEFAULT false,
  UNIQUE (society_id, name, held_on)
);

CREATE TABLE event_contributions (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id      UUID NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
  flat_id       UUID REFERENCES flats(id) ON DELETE RESTRICT,
  sponsor_name  TEXT,
  amount        BIGINT NOT NULL CHECK (amount > 0),
  received_on   DATE NOT NULL,
  payment_id    UUID REFERENCES payments(id),
  -- A contribution is from a flat or an outside sponsor, not neither.
  CHECK (flat_id IS NOT NULL OR sponsor_name IS NOT NULL)
);

CREATE TABLE event_expenses (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id      UUID NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
  description   TEXT NOT NULL,
  amount        BIGINT NOT NULL CHECK (amount > 0),
  incurred_on   DATE NOT NULL,
  vendor_id     UUID,
  posted_entry_id UUID REFERENCES journal_entries(id)
);

-- --------------------------------------------------------------------------
-- Vendors
-- --------------------------------------------------------------------------
CREATE TABLE vendors (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  name          TEXT NOT NULL,
  category      TEXT NOT NULL,
  pan           TEXT CHECK (pan IS NULL OR pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$'),
  gstin         TEXT CHECK (gstin IS NULL OR length(gstin) = 15),
  -- Which section applies to this vendor's work, and whether they are a
  -- company: 194C is 2% for a company and 1% for an individual or HUF.
  tds_section   TEXT CHECK (tds_section IN ('194C','194J','194I','none')),
  payee_kind    TEXT CHECK (payee_kind IN ('company','individual-or-huf')),
  bank_last4    TEXT CHECK (bank_last4 IS NULL OR bank_last4 ~ '^[0-9]{4}$'),
  bank_ifsc     TEXT CHECK (bank_ifsc IS NULL OR bank_ifsc ~ '^[A-Z]{4}0[A-Z0-9]{6}$'),
  active        BOOLEAN NOT NULL DEFAULT true,
  UNIQUE (society_id, name)
);

COMMENT ON TABLE vendors IS
  'No internet-banking credential has a column here, by design. Last four digits and IFSC are enough to identify an account on a payment advice.';

CREATE TABLE vendor_contracts (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id     UUID NOT NULL REFERENCES vendors(id) ON DELETE RESTRICT,
  title         TEXT NOT NULL,
  starts_on     DATE NOT NULL,
  ends_on       DATE NOT NULL,
  monthly_value BIGINT CHECK (monthly_value IS NULL OR monthly_value > 0),
  renewal_notice_days SMALLINT NOT NULL DEFAULT 30,
  CHECK (ends_on > starts_on)
);

CREATE TABLE vendor_bills (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  vendor_id       UUID NOT NULL REFERENCES vendors(id) ON DELETE RESTRICT,
  bill_no         TEXT NOT NULL,
  bill_date       DATE NOT NULL,
  received_on     DATE,
  expense_account TEXT NOT NULL,
  gross           BIGINT NOT NULL CHECK (gross > 0),
  input_gst       BIGINT NOT NULL DEFAULT 0 CHECK (input_gst >= 0),
  tds_section     TEXT NOT NULL CHECK (tds_section IN ('194C','194J','194I','none')),
  tds_rate_bps    INTEGER NOT NULL DEFAULT 0 CHECK (tds_rate_bps >= 0),
  tds_amount      BIGINT NOT NULL DEFAULT 0 CHECK (tds_amount >= 0),
  net_payable     BIGINT NOT NULL CHECK (net_payable >= 0),
  -- Approval, booking and payment are distinct. 'approved' posts nothing.
  state           TEXT NOT NULL CHECK (state IN
                   ('awaiting-approval','approved','booked','rejected')),
  approved_by     UUID REFERENCES users(id),
  rejected_reason TEXT,
  posted_entry_id UUID REFERENCES journal_entries(id),
  UNIQUE (society_id, vendor_id, bill_no),
  FOREIGN KEY (society_id, expense_account) REFERENCES accounts(society_id, code),
  CHECK (tds_amount <= gross),
  CHECK (net_payable = gross - tds_amount),
  CHECK (state <> 'approved' OR approved_by IS NOT NULL),
  CHECK (state <> 'booked' OR (approved_by IS NOT NULL AND posted_entry_id IS NOT NULL)),
  CHECK (state <> 'rejected' OR rejected_reason IS NOT NULL)
);

CREATE TABLE vendor_payments (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  vendor_id       UUID NOT NULL REFERENCES vendors(id) ON DELETE RESTRICT,
  bill_id         UUID REFERENCES vendor_bills(id) ON DELETE RESTRICT,
  payment_ref     TEXT NOT NULL,
  paid_on         DATE NOT NULL,
  amount          BIGINT NOT NULL CHECK (amount > 0),
  method          TEXT NOT NULL,
  bank_account_id UUID,
  posted_entry_id UUID REFERENCES journal_entries(id),
  idempotency_key TEXT NOT NULL,
  UNIQUE (society_id, payment_ref),
  UNIQUE (society_id, idempotency_key)
);

CREATE RULE vendor_payments_no_delete AS ON DELETE TO vendor_payments DO INSTEAD NOTHING;

-- --------------------------------------------------------------------------
-- GST and TDS registers
-- --------------------------------------------------------------------------
CREATE TABLE gst_register (
  id              BIGSERIAL PRIMARY KEY,
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  document_id     UUID REFERENCES billing_documents(id),
  adjustment_id   UUID REFERENCES invoice_adjustments(id),
  tax_period      TEXT NOT NULL,
  invoice_no      TEXT NOT NULL,
  invoice_date    DATE NOT NULL,
  counterparty    TEXT NOT NULL,
  counterparty_gstin TEXT,
  -- B2B where the member supplied a GSTIN, B2C otherwise. Drives GSTR-1.
  supply_type     TEXT NOT NULL CHECK (supply_type IN ('B2B','B2C')),
  sac_code        TEXT,
  taxable_value   BIGINT NOT NULL CHECK (taxable_value >= 0),
  cgst            BIGINT NOT NULL DEFAULT 0 CHECK (cgst >= 0),
  sgst            BIGINT NOT NULL DEFAULT 0 CHECK (sgst >= 0),
  igst            BIGINT NOT NULL DEFAULT 0 CHECK (igst >= 0),
  rate_bps        INTEGER NOT NULL CHECK (rate_bps >= 0),
  reverse_charge  BOOLEAN NOT NULL DEFAULT false,
  -- An entry belongs to an invoice or an adjustment, exactly one.
  CHECK ((document_id IS NULL) <> (adjustment_id IS NULL)),
  -- Intra-state is CGST plus SGST; inter-state is IGST. Not both.
  CHECK ((igst = 0) OR (cgst = 0 AND sgst = 0))
);

CREATE INDEX gst_register_by_period ON gst_register (society_id, tax_period);
CREATE RULE gst_register_no_delete AS ON DELETE TO gst_register DO INSTEAD NOTHING;

CREATE TABLE tds_register (
  id              BIGSERIAL PRIMARY KEY,
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  bill_id         UUID REFERENCES vendor_bills(id),
  vendor_id       UUID NOT NULL REFERENCES vendors(id),
  section         TEXT NOT NULL CHECK (section IN ('194C','194J','194I')),
  quarter         TEXT NOT NULL CHECK (quarter ~ '^Q[1-4]-FY[0-9]{2}-[0-9]{2}$'),
  deducted_on     DATE NOT NULL,
  gross           BIGINT NOT NULL CHECK (gross > 0),
  rate_bps        INTEGER NOT NULL CHECK (rate_bps > 0),
  tds_amount      BIGINT NOT NULL CHECK (tds_amount > 0),
  -- Set when the challan is recorded. Null means still a liability.
  challan_no      TEXT,
  challan_date    DATE,
  remittance_entry_id UUID REFERENCES journal_entries(id),
  CHECK ((challan_no IS NULL) = (challan_date IS NULL))
);

CREATE INDEX tds_register_by_quarter ON tds_register (society_id, quarter);
CREATE INDEX tds_register_unremitted ON tds_register (society_id, section)
  WHERE challan_no IS NULL;
CREATE RULE tds_register_no_delete AS ON DELETE TO tds_register DO INSTEAD NOTHING;

-- --------------------------------------------------------------------------
-- Banking
-- --------------------------------------------------------------------------
CREATE TABLE bank_accounts (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  label           TEXT NOT NULL,
  bank_name       TEXT NOT NULL,
  -- Last four only, and IFSC. There is deliberately no column for a full
  -- account number, a customer id, a password, or an API secret: a
  -- reconciliation system needs none of them, and storing them makes this
  -- database worth attacking.
  account_last4   TEXT NOT NULL CHECK (account_last4 ~ '^[0-9]{4}$'),
  ifsc            TEXT NOT NULL CHECK (ifsc ~ '^[A-Z]{4}0[A-Z0-9]{6}$'),
  ledger_account  TEXT NOT NULL,
  purpose         TEXT NOT NULL CHECK (purpose IN ('operating','sinking','festival','other')),
  active          BOOLEAN NOT NULL DEFAULT true,
  UNIQUE (society_id, label),
  FOREIGN KEY (society_id, ledger_account) REFERENCES accounts(society_id, code)
);

ALTER TABLE payments ADD CONSTRAINT payments_bank_account_fk
  FOREIGN KEY (bank_account_id) REFERENCES bank_accounts(id);
ALTER TABLE vendor_payments ADD CONSTRAINT vendor_payments_bank_account_fk
  FOREIGN KEY (bank_account_id) REFERENCES bank_accounts(id);

CREATE TABLE statement_imports (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  bank_account_id UUID NOT NULL REFERENCES bank_accounts(id) ON DELETE RESTRICT,
  format          TEXT NOT NULL CHECK (format IN ('csv','xlsx','mt940')),
  filename        TEXT NOT NULL,
  -- Hash of the file, so the same statement cannot be imported twice.
  content_sha256  TEXT NOT NULL,
  period_from     DATE,
  period_to       DATE,
  rows_total      INTEGER NOT NULL DEFAULT 0,
  rows_imported   INTEGER NOT NULL DEFAULT 0,
  rows_duplicate  INTEGER NOT NULL DEFAULT 0,
  rows_rejected   INTEGER NOT NULL DEFAULT 0,
  imported_by     UUID REFERENCES users(id),
  imported_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (society_id, bank_account_id, content_sha256)
);

CREATE TABLE bank_transactions (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  bank_account_id UUID NOT NULL REFERENCES bank_accounts(id) ON DELETE RESTRICT,
  import_id       UUID REFERENCES statement_imports(id),
  value_date      DATE NOT NULL,
  narration       TEXT NOT NULL,
  reference       TEXT,
  -- Signed: positive is money in.
  amount          BIGINT NOT NULL CHECK (amount <> 0),
  running_balance BIGINT,
  -- The deduplication key: the bank's own reference where it gives one, else a
  -- hash of date, amount and narration. Unique per account.
  dedupe_key      TEXT NOT NULL,
  state           TEXT NOT NULL DEFAULT 'unmatched'
                  CHECK (state IN ('unmatched','suggested','matched','suspense','ignored')),
  matched_payment_id UUID REFERENCES payments(id),
  matched_vendor_payment_id UUID REFERENCES vendor_payments(id),
  matched_by      UUID REFERENCES users(id),
  matched_at      TIMESTAMPTZ,
  suspense_reason TEXT,
  UNIQUE (society_id, bank_account_id, dedupe_key),
  -- A matched row points at exactly one side.
  CHECK (state <> 'matched' OR
         ((matched_payment_id IS NULL) <> (matched_vendor_payment_id IS NULL))),
  CHECK (state <> 'suspense' OR suspense_reason IS NOT NULL)
);

CREATE INDEX bank_transactions_open
  ON bank_transactions (society_id, bank_account_id, value_date)
  WHERE state IN ('unmatched','suggested','suspense');

CREATE TABLE bank_reconciliations (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id        UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  bank_account_id   UUID NOT NULL REFERENCES bank_accounts(id) ON DELETE RESTRICT,
  as_at             DATE NOT NULL,
  statement_balance BIGINT NOT NULL,
  ledger_balance    BIGINT NOT NULL,
  unmatched_count   INTEGER NOT NULL DEFAULT 0,
  difference        BIGINT NOT NULL,
  reconciled_by     UUID REFERENCES users(id),
  reconciled_at     TIMESTAMPTZ,
  UNIQUE (society_id, bank_account_id, as_at),
  -- The difference is derived and must agree, so a reconciliation cannot be
  -- recorded as clean while the two sides disagree.
  CHECK (difference = statement_balance - ledger_balance),
  CHECK (reconciled_by IS NULL OR difference = 0)
);

COMMENT ON CONSTRAINT bank_reconciliations_check1 ON bank_reconciliations IS
  'A reconciliation can only be signed off when the difference is zero.';

-- Per-flat virtual accounts, for when a bank provides them.
CREATE TABLE virtual_accounts (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  flat_id         UUID NOT NULL REFERENCES flats(id) ON DELETE RESTRICT,
  bank_account_id UUID NOT NULL REFERENCES bank_accounts(id) ON DELETE RESTRICT,
  virtual_ref     TEXT NOT NULL,
  upi_id          TEXT,
  provider        TEXT NOT NULL,
  active          BOOLEAN NOT NULL DEFAULT true,
  UNIQUE (society_id, virtual_ref),
  UNIQUE (society_id, flat_id, bank_account_id)
);

-- --------------------------------------------------------------------------
-- Helpdesk
-- --------------------------------------------------------------------------
CREATE TABLE ticket_categories (
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  key           TEXT NOT NULL,
  label         TEXT NOT NULL,
  -- The SLA, in hours, as a setting rather than a constant in code.
  sla_hours     INTEGER NOT NULL CHECK (sla_hours > 0),
  escalate_to_role TEXT CHECK (escalate_to_role IN
                    ('manager','treasurer','secretary')),
  PRIMARY KEY (society_id, key)
);

CREATE TABLE tickets (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  ticket_no       TEXT NOT NULL,
  flat_id         UUID REFERENCES flats(id) ON DELETE RESTRICT,
  raised_by       UUID REFERENCES users(id),
  category        TEXT NOT NULL,
  description     TEXT NOT NULL CHECK (length(btrim(description)) > 0),
  priority        TEXT NOT NULL DEFAULT 'normal'
                  CHECK (priority IN ('emergency','high','normal','low')),
  state           TEXT NOT NULL DEFAULT 'open'
                  CHECK (state IN ('open','assigned','in-progress','resolved','confirmed','closed','reopened')),
  assigned_to_user UUID REFERENCES users(id),
  assigned_to_vendor UUID REFERENCES vendors(id),
  raised_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  due_at          TIMESTAMPTZ NOT NULL,
  resolved_at     TIMESTAMPTZ,
  confirmed_at    TIMESTAMPTZ,
  closed_at       TIMESTAMPTZ,
  reopened_count  SMALLINT NOT NULL DEFAULT 0 CHECK (reopened_count >= 0),
  escalated_at    TIMESTAMPTZ,
  resolution_note TEXT,
  satisfaction    SMALLINT CHECK (satisfaction IS NULL OR satisfaction BETWEEN 1 AND 5),
  cost            BIGINT CHECK (cost IS NULL OR cost >= 0),
  UNIQUE (society_id, ticket_no),
  FOREIGN KEY (society_id, category) REFERENCES ticket_categories(society_id, key),
  CHECK (state <> 'resolved' OR (resolved_at IS NOT NULL AND resolution_note IS NOT NULL)),
  CHECK (state <> 'confirmed' OR confirmed_at IS NOT NULL),
  -- Assigned to a person or a vendor, not both.
  CHECK (assigned_to_user IS NULL OR assigned_to_vendor IS NULL)
);

CREATE INDEX tickets_open ON tickets (society_id, due_at)
  WHERE state IN ('open','assigned','in-progress','reopened');

CREATE TABLE ticket_events (
  id            BIGSERIAL PRIMARY KEY,
  ticket_id     UUID NOT NULL REFERENCES tickets(id) ON DELETE RESTRICT,
  at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_user    UUID REFERENCES users(id),
  actor_label   TEXT NOT NULL,
  from_state    TEXT,
  to_state      TEXT,
  note          TEXT
);

CREATE RULE ticket_events_no_delete AS ON DELETE TO ticket_events DO INSTEAD NOTHING;

CREATE TABLE attachments (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  ticket_id       UUID REFERENCES tickets(id) ON DELETE RESTRICT,
  document_id     UUID REFERENCES billing_documents(id) ON DELETE RESTRICT,
  vendor_bill_id  UUID REFERENCES vendor_bills(id) ON DELETE RESTRICT,
  filename        TEXT NOT NULL,
  content_type    TEXT NOT NULL,
  byte_size       INTEGER NOT NULL CHECK (byte_size > 0),
  sha256          TEXT NOT NULL,
  -- Where the bytes live. Object storage in production; the filesystem in
  -- development. Never the database itself.
  storage_key     TEXT NOT NULL,
  uploaded_by     UUID REFERENCES users(id),
  uploaded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (society_id, storage_key),
  -- An attachment hangs off exactly one thing.
  CHECK ((ticket_id IS NOT NULL)::int
       + (document_id IS NOT NULL)::int
       + (vendor_bill_id IS NOT NULL)::int = 1)
);

-- --------------------------------------------------------------------------
-- Generated documents and notification delivery
-- --------------------------------------------------------------------------
CREATE TABLE generated_documents (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  kind            TEXT NOT NULL CHECK (kind IN
                   ('tax-invoice','proforma','receipt','credit-note','debit-note','statement','report')),
  document_id     UUID REFERENCES billing_documents(id),
  payment_id      UUID REFERENCES payments(id),
  adjustment_id   UUID REFERENCES invoice_adjustments(id),
  content_type    TEXT NOT NULL DEFAULT 'application/pdf',
  byte_size       INTEGER CHECK (byte_size IS NULL OR byte_size > 0),
  sha256          TEXT,
  storage_key     TEXT,
  generated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- The data the document was rendered from, so a reprint is byte-identical
  -- and a later rate change cannot alter a document already issued.
  render_payload  JSONB NOT NULL
);

CREATE TABLE notifications (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  channel         TEXT NOT NULL CHECK (channel IN ('email','sms','whatsapp','in-app')),
  template        TEXT NOT NULL,
  to_user         UUID REFERENCES users(id),
  to_address      TEXT NOT NULL,
  subject         TEXT,
  payload         JSONB NOT NULL,
  document_id     UUID REFERENCES generated_documents(id),
  state           TEXT NOT NULL DEFAULT 'queued'
                  CHECK (state IN ('queued','sending','sent','failed','bounced','suppressed')),
  attempts        SMALLINT NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  -- The provider's own id, which is the only thing that makes 'sent' mean
  -- anything. Null with state 'sent' is not allowed.
  provider        TEXT,
  provider_message_id TEXT,
  last_error      TEXT,
  queued_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at         TIMESTAMPTZ,
  CHECK (state <> 'sent' OR (provider IS NOT NULL AND provider_message_id IS NOT NULL AND sent_at IS NOT NULL)),
  CHECK (state <> 'failed' OR last_error IS NOT NULL)
);

COMMENT ON CONSTRAINT notifications_check1 ON notifications IS
  'A notification cannot be marked sent without a provider and that provider''s message id. Nothing may record a delivery it cannot evidence.';

CREATE INDEX notifications_pending ON notifications (society_id, queued_at)
  WHERE state IN ('queued','sending');

-- --------------------------------------------------------------------------
-- Committee approvals and resolutions
-- --------------------------------------------------------------------------
CREATE TABLE resolutions (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  reference       TEXT NOT NULL,
  passed_on       DATE NOT NULL,
  meeting_kind    TEXT NOT NULL CHECK (meeting_kind IN ('committee','agm','sgm')),
  subject         TEXT NOT NULL,
  body            TEXT NOT NULL,
  UNIQUE (society_id, reference)
);

CREATE TABLE approvals (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id      UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  subject_table   TEXT NOT NULL,
  subject_id      TEXT NOT NULL,
  -- Maker-checker: whoever prepared it cannot be whoever approves it.
  requested_by    UUID NOT NULL REFERENCES users(id),
  requested_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_by      UUID REFERENCES users(id),
  decided_at      TIMESTAMPTZ,
  decision        TEXT CHECK (decision IN ('approved','rejected')),
  reason          TEXT,
  resolution_id   UUID REFERENCES resolutions(id),
  CHECK (decided_by IS NULL OR decided_by <> requested_by),
  CHECK ((decision IS NULL) = (decided_at IS NULL)),
  CHECK (decision <> 'rejected' OR reason IS NOT NULL)
);

COMMENT ON CONSTRAINT approvals_check ON approvals IS
  'Maker-checker, at the database: the requester cannot be the approver.';

CREATE INDEX approvals_pending ON approvals (society_id, subject_table)
  WHERE decision IS NULL;

-- --------------------------------------------------------------------------
-- Financial period locks
-- --------------------------------------------------------------------------
CREATE TABLE financial_periods (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  -- 'YYYY-MM' for a month.
  period        TEXT NOT NULL CHECK (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  starts_on     DATE NOT NULL,
  ends_on       DATE NOT NULL,
  state         TEXT NOT NULL DEFAULT 'open'
                CHECK (state IN ('open','closing','closed','reopened')),
  closed_by     UUID REFERENCES users(id),
  closed_at     TIMESTAMPTZ,
  reopened_by   UUID REFERENCES users(id),
  reopened_reason TEXT,
  trial_balance_debit  BIGINT,
  trial_balance_credit BIGINT,
  UNIQUE (society_id, period),
  CHECK (ends_on >= starts_on),
  CHECK (state <> 'closed' OR (closed_by IS NOT NULL AND closed_at IS NOT NULL)),
  CHECK (state <> 'reopened' OR (reopened_by IS NOT NULL AND reopened_reason IS NOT NULL)),
  -- A closed period records the trial balance it closed on, and it must tie.
  CHECK (state <> 'closed' OR
         (trial_balance_debit IS NOT NULL AND trial_balance_debit = trial_balance_credit))
);

-- Posting into a closed period is refused by the database, not only by the
-- application. This is the lock.
CREATE OR REPLACE FUNCTION check_period_open() RETURNS TRIGGER AS $$
DECLARE
  period_state TEXT;
  label TEXT;
BEGIN
  label := to_char(NEW.entry_date, 'YYYY-MM');
  SELECT state INTO period_state FROM financial_periods
   WHERE society_id = NEW.society_id AND period = label;

  IF period_state IN ('closed', 'closing') THEN
    RAISE EXCEPTION
      'cannot post into % because that period is %; reopen it or post to an open period',
      label, period_state;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER journal_entries_period_open
  BEFORE INSERT ON journal_entries
  FOR EACH ROW EXECUTE FUNCTION check_period_open();

-- --------------------------------------------------------------------------
-- Scheduled jobs
-- --------------------------------------------------------------------------
CREATE TABLE scheduled_jobs (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id    UUID REFERENCES societies(id) ON DELETE RESTRICT,
  kind          TEXT NOT NULL,
  -- The business key for this run, so a scheduler firing twice does the work
  -- once. 'monthly-billing:2026-07' can only exist once.
  run_key       TEXT NOT NULL,
  scheduled_for TIMESTAMPTZ NOT NULL,
  state         TEXT NOT NULL DEFAULT 'pending'
                CHECK (state IN ('pending','running','succeeded','failed','abandoned')),
  attempts      SMALLINT NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  max_attempts  SMALLINT NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
  -- When to try again, set by the backoff.
  next_attempt_at TIMESTAMPTZ,
  locked_by     TEXT,
  locked_at     TIMESTAMPTZ,
  payload       JSONB NOT NULL DEFAULT '{}'::jsonb,
  result        JSONB,
  last_error    TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at   TIMESTAMPTZ,
  UNIQUE (kind, run_key),
  CHECK (state <> 'failed' OR last_error IS NOT NULL),
  CHECK (state <> 'running' OR locked_by IS NOT NULL)
);

CREATE INDEX scheduled_jobs_due ON scheduled_jobs (state, scheduled_for)
  WHERE state IN ('pending', 'running');

-- --------------------------------------------------------------------------
-- Rate limiting, for login and OTP
-- --------------------------------------------------------------------------
CREATE TABLE rate_limit_buckets (
  -- The subject: an email, an IP, a user id. Hashed by the application so the
  -- table is not a list of who tried to log in.
  subject_hash  TEXT NOT NULL,
  action        TEXT NOT NULL,
  window_start  TIMESTAMPTZ NOT NULL,
  count         INTEGER NOT NULL DEFAULT 1 CHECK (count > 0),
  PRIMARY KEY (subject_hash, action, window_start)
);

CREATE INDEX rate_limit_buckets_sweep ON rate_limit_buckets (window_start);

COMMIT;


-- ====================================================================
-- 004_fix_allocation_guard.sql
-- ====================================================================

-- Migration 004: fix the receipt-allocation guard.
--
-- Migration 003 attached one trigger function to both `receipt_allocations`
-- and `payments`. It reads NEW.payment_id, which exists on the allocation row
-- but not on the payment row — where the column is `id` — so every insert into
-- `payments` failed with "record new has no field payment_id". The constraint
-- was unusable in both directions: it could not pass, so it also could not
-- catch anything.
--
-- Split into two functions over one shared check. Added as a new migration
-- rather than by editing 003, because 003 has been applied and editing an
-- applied migration is how two deployments end up on the same version number
-- with different schemas.

BEGIN;

-- The check itself, taking the payment id directly.
CREATE OR REPLACE FUNCTION assert_payment_fully_allocated(pid UUID) RETURNS VOID AS $$
DECLARE
  allocated BIGINT;
  received BIGINT;
BEGIN
  SELECT amount INTO received FROM payments WHERE id = pid;
  IF received IS NULL THEN
    RAISE EXCEPTION 'allocation references payment % which does not exist', pid;
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO allocated
    FROM receipt_allocations WHERE payment_id = pid;

  IF allocated <> received THEN
    RAISE EXCEPTION
      'payment % received % paise but its allocations total % (out by %)',
      pid, received, allocated, allocated - received;
  END IF;
END;
$$ LANGUAGE plpgsql;

-- Fired from an allocation row, which carries payment_id.
CREATE OR REPLACE FUNCTION check_allocation_covers_payment() RETURNS TRIGGER AS $$
BEGIN
  PERFORM assert_payment_fully_allocated(COALESCE(NEW.payment_id, OLD.payment_id));
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Fired from the payment row, whose own key is `id`. This is the case that
-- catches a payment inserted with no allocations at all, which the allocation
-- trigger cannot see because no allocation row ever arrives.
CREATE OR REPLACE FUNCTION check_payment_is_allocated() RETURNS TRIGGER AS $$
BEGIN
  PERFORM assert_payment_fully_allocated(NEW.id);
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS receipt_allocations_cover_payment ON receipt_allocations;
DROP TRIGGER IF EXISTS payments_are_allocated ON payments;
DROP FUNCTION IF EXISTS check_payment_allocated();

CREATE CONSTRAINT TRIGGER receipt_allocations_cover_payment
  AFTER INSERT OR UPDATE ON receipt_allocations
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_allocation_covers_payment();

CREATE CONSTRAINT TRIGGER payments_are_allocated
  AFTER INSERT ON payments
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_payment_is_allocated();

COMMIT;


-- ====================================================================
-- 005_login_identity.sql
-- ====================================================================

-- Migration 005: one account per address, and the notification queue's index.
--
-- 001 made (society_id, email) unique, which is right for a society's member
-- list and wrong for signing in: the login path is given an address and
-- nothing else, so with a demo society and a production society in the same
-- database two rows could share an address and `LIMIT 1` would pick one of
-- them arbitrarily. A resident could be signed in against the wrong society's
-- data, which is the worst kind of bug to find late.
--
-- The fix is an index, not application code: an address identifies at most one
-- active account across the whole database.

BEGIN;

-- Addresses are stored lower-cased by the application; the index says so too,
-- so a row inserted by hand cannot slip a second 'Owner@...' past it.
CREATE UNIQUE INDEX users_one_active_email
  ON users (lower(email))
  WHERE is_active;

COMMENT ON INDEX users_one_active_email IS
  'Sign-in is by address alone, so an address must identify at most one active account across every society in this database. Deactivated accounts are excluded so a former resident''s address can be reused.';

-- The dispatch worker reads this every pass.
CREATE INDEX notifications_queued_email
  ON notifications (society_id, queued_at)
  WHERE state = 'queued' AND channel = 'email';

COMMIT;


-- ====================================================================
-- 006_gst_register_notes.sql
-- ====================================================================

-- Migration 006: credit and debit notes in the GST register.
--
-- 003 assumed every row in `gst_register` was an invoice, and gave the tax
-- columns `CHECK (cgst >= 0)`. That is right for an invoice and wrong for the
-- register as a whole: a credit note reduces the output tax for its period,
-- and the first one raised was refused by that constraint.
--
-- Storing it as a negative invoice would have been the smaller change and the
-- wrong one. A return does not report a credit note as a negative invoice — it
-- reports it in its own table (CDNR), with positive figures and a reference to
-- the invoice it adjusts. So the row says which kind of document it is, keeps
-- its amounts positive, and the summary nets them.

BEGIN;

ALTER TABLE gst_register
  ADD COLUMN entry_kind TEXT NOT NULL DEFAULT 'invoice'
    CHECK (entry_kind IN ('invoice', 'credit-note', 'debit-note'));

COMMENT ON COLUMN gst_register.entry_kind IS
  'Which table of a return this row belongs to: B2B/B2C for an invoice, CDNR for a note. Amounts are always positive; a credit note reduces the period total by being subtracted, not by being stored negative.';

-- An adjustment row is a note, and an invoice row is not. Enforced, because
-- the two are already distinguishable by which id is set and a row that
-- disagreed with itself would misstate a return.
ALTER TABLE gst_register
  ADD CONSTRAINT gst_register_kind_matches_subject
  CHECK (
    (entry_kind = 'invoice' AND document_id IS NOT NULL)
    OR (entry_kind IN ('credit-note', 'debit-note') AND adjustment_id IS NOT NULL)
  );

CREATE INDEX gst_register_by_kind ON gst_register (society_id, tax_period, entry_kind);

COMMIT;


-- ====================================================================
-- 007_canonical_billing_period.sql
-- ====================================================================

-- Migration 007: one spelling for a billing period.
--
-- `billing_documents.period` is free text, and the duplicate-billing guard —
-- the partial unique index billing_documents_one_live_per_period — compares
-- it as text. The API accepted "Jul  2026" (two spaces) as a period, stored it
-- as written, and the index then saw it as a different month from "Jul 2026":
-- the same flat could be billed for July twice. The application now writes the
-- canonical form ("Jul 2026": three-letter month, one space, four-digit year);
-- this migration makes the database insist on it, so nothing that bypasses the
-- application can reintroduce the duplicate.
--
-- Two parts:
--
--  1. Existing rows are rewritten into the canonical form where that is safe —
--     a cancelled document, or a live one that would not then collide with
--     another live document for the same flat and month. A collision is the
--     very duplicate this guards against, and choosing which of two live
--     bills to keep is a decision for a person, not a migration, so those rows
--     are left as they are and reported with a NOTICE.
--
--  2. A trigger refuses a non-canonical period on INSERT, and on an UPDATE that
--     changes the period. A CHECK constraint would also refuse unrelated
--     updates (cancelling, converting) to any row step 1 had to leave alone,
--     which would make exactly those duplicates impossible to cancel.

BEGIN;

-- 1. Rewrite what can be rewritten.
WITH parsed AS (
  SELECT d.id, d.society_id, d.flat_id, d.state, d.period,
         initcap(lower(left(m[1], 3))) || ' ' || m[2] AS canonical
    FROM billing_documents d,
         LATERAL regexp_match(
           d.period,
           '^\s*(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s+([0-9]{4})\s*$',
           'i'
         ) AS m
),
live_per_month AS (
  SELECT society_id, flat_id, canonical, count(*) AS live
    FROM parsed
   WHERE state <> 'cancelled'
   GROUP BY society_id, flat_id, canonical
)
UPDATE billing_documents d
   SET period = p.canonical
  FROM parsed p
  -- LEFT, because a cancelled row with no live sibling has no row here. It
  -- collides with nothing (the unique index ignores cancelled documents), so
  -- it is rewritten too.
  LEFT JOIN live_per_month l
    ON l.society_id = p.society_id AND l.flat_id = p.flat_id AND l.canonical = p.canonical
 WHERE d.id = p.id
   AND d.period <> p.canonical
   AND (p.state = 'cancelled' OR l.live = 1);

DO $$
DECLARE
  remaining INTEGER;
BEGIN
  SELECT count(*) INTO remaining
    FROM billing_documents
   WHERE period !~ '^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) [0-9]{4}$';
  IF remaining > 0 THEN
    RAISE NOTICE
      '% billing document(s) keep a non-canonical period because rewriting them would '
      'collide with another live document for the same flat and month — a duplicate bill. '
      'Cancel the one that should not stand: SELECT id, flat_id, period, state FROM '
      'billing_documents WHERE period !~ ''^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) [0-9]{4}$'';',
      remaining;
  END IF;
END;
$$;

-- 2. Refuse anything else from now on.
CREATE OR REPLACE FUNCTION check_billing_period_canonical() RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.period IS NOT DISTINCT FROM OLD.period THEN
    RETURN NEW;
  END IF;
  IF NEW.period !~ '^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) [0-9]{4}$' THEN
    RAISE EXCEPTION
      'billing period "%" is not written the one way a period is written, such as "Jul 2026" '
      '(three-letter month, one space, four-digit year); two spellings of one month would '
      'defeat the duplicate-billing check', NEW.period;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER billing_documents_period_canonical
  BEFORE INSERT OR UPDATE OF period ON billing_documents
  FOR EACH ROW EXECUTE FUNCTION check_billing_period_canonical();

COMMENT ON COLUMN billing_documents.period IS
  'The billing month as "Jul 2026": three-letter month, one space, four-digit year. Enforced by trigger billing_documents_period_canonical, because the one-live-document-per-period index compares this as text.';

COMMIT;


-- ====================================================================
-- 008_security_hardening.sql
-- ====================================================================

-- Migration 008: maker-checker on rates and settings, and job keys per society.
--
-- A rate or a society setting was approved by "someone with rate.approve",
-- with nothing to say who had entered it. One account holding both roles
-- could type a GST treatment and then sign it off. Each row now records who
-- proposed it, and the database refuses an approval by that same person.
--
-- Scheduled jobs were unique on (kind, run_key) across every society, so one
-- society could claim another's run key first and make its schedule fail.
-- The key now includes the society. NULLS NOT DISTINCT keeps the old
-- behaviour for jobs that belong to no society (PostgreSQL 15 and later).

BEGIN;

ALTER TABLE maintenance_rates
  ADD COLUMN requested_by UUID REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE maintenance_rates
  ADD CONSTRAINT maintenance_rates_maker_is_not_checker
  CHECK (requested_by IS NULL OR approved_by IS NULL OR requested_by <> approved_by);

ALTER TABLE society_settings
  ADD COLUMN requested_by UUID REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE society_settings
  ADD CONSTRAINT society_settings_maker_is_not_checker
  CHECK (requested_by IS NULL OR approved_by IS NULL OR requested_by <> approved_by);

ALTER TABLE scheduled_jobs DROP CONSTRAINT scheduled_jobs_kind_run_key_key;
ALTER TABLE scheduled_jobs
  ADD CONSTRAINT scheduled_jobs_society_kind_run_key_key
  UNIQUE NULLS NOT DISTINCT (society_id, kind, run_key);

COMMIT;


-- ====================================================================
-- 009_bank_match_once.sql
-- ====================================================================

-- Migration 009: a payment matches at most one statement line.
--
-- Nothing stopped the same receipt (or vendor payment) being matched to two
-- bank lines, which reconciles one movement of money twice and hides a line
-- that has no counterpart. The match route now checks; these indexes make
-- the database refuse it too, including two matches made at the same moment.

BEGIN;

CREATE UNIQUE INDEX bank_transactions_payment_matched_once
  ON bank_transactions (matched_payment_id)
  WHERE state = 'matched' AND matched_payment_id IS NOT NULL;

CREATE UNIQUE INDEX bank_transactions_vendor_payment_matched_once
  ON bank_transactions (matched_vendor_payment_id)
  WHERE state = 'matched' AND matched_vendor_payment_id IS NOT NULL;

COMMIT;


-- ====================================================================
-- 010_opening_balances.sql
-- ====================================================================

-- Migration 010: going live — opening balances and the society's profile.
--
-- A society that starts using SocietyBooks part-way through its life brings
-- its position with it: what each flat owed or had paid ahead on the cut-over
-- date, and what the society held in the bank, in its funds and deposits, and
-- owed its vendors. Until now there was nowhere to put any of that, so the
-- first trial balance would have started at zero and every member's dues
-- would have been wrong from the first bill.
--
-- The design keeps the opening position inside the double-entry model rather
-- than beside it:
--
--  · The whole position posts as ONE journal entry (source_kind
--    'opening-balance'), so the deferred balance trigger from 002 refuses it
--    exactly as it refuses any other unbalanced entry, and the period lock
--    from 003 refuses it in a closed month.
--
--  · A flat's opening due becomes a billing document of its own, in state
--    'tax-invoice' and tagged with its batch. That is what makes it behave
--    "exactly like an invoice": the receipt allocator, the ageing report, the
--    dues screen and the flat statement all read documents in that state, so
--    an old arrear is settled oldest-first and ages like any bill without a
--    second code path. It is not a supply, so it carries no tax: a CHECK keeps
--    its estimated tax at zero and a trigger keeps it out of the GST register.
--
--  · An opening vendor payable becomes a booked vendor bill, so the existing
--    payment route can settle it against its own bill number.
--
--  · Entry is maker-checker: one person prepares a draft, another approves it,
--    and approval is what posts. At most one batch per society is live; a
--    correction is a reversal of the posted batch followed by a new one, both
--    of which stay in the ledger.

BEGIN;

-- --------------------------------------------------------------------------
-- The society's profile
-- --------------------------------------------------------------------------
ALTER TABLE societies ADD COLUMN tan TEXT;
ALTER TABLE societies ADD COLUMN address TEXT;
ALTER TABLE societies ADD COLUMN contact_email TEXT;
ALTER TABLE societies ADD COLUMN contact_phone TEXT;

ALTER TABLE societies ADD CONSTRAINT societies_tan_format
  CHECK (tan IS NULL OR tan ~ '^[A-Z]{4}[0-9]{5}[A-Z]$');

-- NOT VALID: a row written before this migration is not re-judged, but every
-- insert and update from now on is. The application validates the same rules
-- (and the GSTIN check digit, which SQL cannot sensibly express) first, so a
-- person sees a sentence rather than a constraint name.
ALTER TABLE societies ADD CONSTRAINT societies_state_code_format
  CHECK (state_code IS NULL OR state_code ~ '^[0-9]{2}$') NOT VALID;
ALTER TABLE societies ADD CONSTRAINT societies_gstin_format
  CHECK (gstin IS NULL OR gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$') NOT VALID;
-- A GSTIN begins with the code of the state it was issued in. One that does
-- not match the society's state is a typo or someone else's registration.
ALTER TABLE societies ADD CONSTRAINT societies_gstin_matches_state
  CHECK (gstin IS NULL OR state_code IS NULL OR left(gstin, 2) = state_code) NOT VALID;

COMMENT ON COLUMN societies.tan IS
  'Tax deduction account number, needed on every TDS challan and Form 16A. Null until the association supplies its own.';

-- --------------------------------------------------------------------------
-- Opening balance batches
-- --------------------------------------------------------------------------
CREATE TABLE opening_balance_batches (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  society_id        UUID NOT NULL REFERENCES societies(id) ON DELETE RESTRICT,
  -- 1 for the first attempt, 2 for the entry that replaces a reversed one.
  batch_no          SMALLINT NOT NULL CHECK (batch_no > 0),
  -- The date the balances are stated at: the last day before the cut-over,
  -- matching the trial balance they were agreed against. The entry is dated
  -- this day.
  as_at             DATE NOT NULL,
  state             TEXT NOT NULL DEFAULT 'draft'
                    CHECK (state IN ('draft','posted','reversed','discarded')),
  -- Whether the difference between debits and credits is posted to the
  -- general reserve as the balancing figure. Off, an unbalanced batch is
  -- refused.
  auto_balance      BOOLEAN NOT NULL DEFAULT false,
  note              TEXT,
  prepared_by       UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  prepared_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  approved_by       UUID REFERENCES users(id) ON DELETE RESTRICT,
  approved_at       TIMESTAMPTZ,
  posted_entry_id   UUID REFERENCES journal_entries(id),
  total_debit       BIGINT CHECK (total_debit IS NULL OR total_debit >= 0),
  total_credit      BIGINT CHECK (total_credit IS NULL OR total_credit >= 0),
  reversed_by       UUID REFERENCES users(id) ON DELETE RESTRICT,
  reversed_at       TIMESTAMPTZ,
  reversal_entry_id UUID REFERENCES journal_entries(id),
  reversal_reason   TEXT,
  UNIQUE (society_id, batch_no),
  -- Maker-checker: whoever prepared the figures cannot be whoever posts them.
  CONSTRAINT opening_balance_maker_is_not_checker
    CHECK (approved_by IS NULL OR approved_by <> prepared_by),
  -- A posted batch names its approver and its entry, and it balanced.
  CHECK (state NOT IN ('posted','reversed') OR (
           approved_by IS NOT NULL AND approved_at IS NOT NULL
           AND posted_entry_id IS NOT NULL
           AND total_debit IS NOT NULL AND total_debit = total_credit AND total_debit > 0)),
  CHECK (state <> 'reversed' OR (
           reversed_by IS NOT NULL AND reversed_at IS NOT NULL
           AND reversal_entry_id IS NOT NULL
           AND reversal_reason IS NOT NULL AND length(btrim(reversal_reason)) > 0))
);

-- Once per society, at the database: at most one batch is being prepared or
-- stands posted. A second opening position next to a posted one would count
-- every balance twice.
CREATE UNIQUE INDEX opening_balance_one_live
  ON opening_balance_batches (society_id)
  WHERE state IN ('draft','posted');

CREATE RULE opening_balance_batches_no_delete AS
  ON DELETE TO opening_balance_batches DO INSTEAD NOTHING;

-- What each flat brought in. A flat either owed or had paid ahead on the
-- cut-over date, never both: the two are netted before entry.
CREATE TABLE opening_balance_flat_lines (
  id            BIGSERIAL PRIMARY KEY,
  batch_id      UUID NOT NULL REFERENCES opening_balance_batches(id) ON DELETE RESTRICT,
  flat_id       UUID NOT NULL REFERENCES flats(id) ON DELETE RESTRICT,
  due           BIGINT NOT NULL DEFAULT 0 CHECK (due >= 0),
  advance       BIGINT NOT NULL DEFAULT 0 CHECK (advance >= 0),
  -- Optional: since when the arrear has been due, so the ageing report shows
  -- a two-year-old arrear as 90+ rather than as last month's.
  due_since     DATE,
  -- The document the due became, set when the batch posts.
  document_id   UUID REFERENCES billing_documents(id),
  UNIQUE (batch_id, flat_id),
  CHECK ((due > 0) <> (advance > 0)),
  CHECK (due_since IS NULL OR due > 0)
);

-- The society-level balances: one row per account (or per vendor bill).
CREATE TABLE opening_balance_account_lines (
  id              BIGSERIAL PRIMARY KEY,
  batch_id        UUID NOT NULL REFERENCES opening_balance_batches(id) ON DELETE RESTRICT,
  society_id      UUID NOT NULL,
  account_code    TEXT NOT NULL,
  debit           BIGINT NOT NULL DEFAULT 0 CHECK (debit >= 0),
  credit          BIGINT NOT NULL DEFAULT 0 CHECK (credit >= 0),
  -- For a vendor payable: whose, and against which of their bills.
  vendor_id       UUID REFERENCES vendors(id) ON DELETE RESTRICT,
  reference       TEXT,
  -- For a vendor payable: what the bill was for, carried onto the booked bill.
  expense_account TEXT,
  memo            TEXT,
  -- True for the figure computed to make the batch balance.
  is_balancing    BOOLEAN NOT NULL DEFAULT false,
  vendor_bill_id  UUID REFERENCES vendor_bills(id),
  CONSTRAINT opening_account_line_one_side CHECK ((debit = 0) <> (credit = 0)),
  CHECK (vendor_id IS NULL OR (reference IS NOT NULL AND expense_account IS NOT NULL)),
  FOREIGN KEY (society_id, account_code) REFERENCES accounts(society_id, code),
  FOREIGN KEY (society_id, expense_account) REFERENCES accounts(society_id, code)
);

CREATE INDEX opening_balance_flat_lines_by_batch ON opening_balance_flat_lines (batch_id);
CREATE INDEX opening_balance_account_lines_by_batch ON opening_balance_account_lines (batch_id);

-- A draft's lines are replaced as it is edited. A posted batch's lines are the
-- record of what was posted and change no further.
CREATE OR REPLACE FUNCTION check_opening_lines_editable() RETURNS TRIGGER AS $$
DECLARE
  batch_state TEXT;
BEGIN
  SELECT state INTO batch_state FROM opening_balance_batches
   WHERE id = COALESCE(OLD.batch_id, NEW.batch_id);
  IF batch_state IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'opening balances that have been %; their lines cannot change. Reverse the batch and enter a new one',
      batch_state;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER opening_balance_flat_lines_editable
  BEFORE UPDATE OR DELETE ON opening_balance_flat_lines
  FOR EACH ROW EXECUTE FUNCTION check_opening_lines_editable();
CREATE TRIGGER opening_balance_account_lines_editable
  BEFORE UPDATE OR DELETE ON opening_balance_account_lines
  FOR EACH ROW EXECUTE FUNCTION check_opening_lines_editable();

-- --------------------------------------------------------------------------
-- Opening items in the billing and vendor registers
-- --------------------------------------------------------------------------
ALTER TABLE billing_documents
  ADD COLUMN opening_batch_id UUID REFERENCES opening_balance_batches(id);
-- An opening due is not a sale and carries no tax.
ALTER TABLE billing_documents ADD CONSTRAINT billing_documents_opening_untaxed
  CHECK (opening_batch_id IS NULL OR estimated_tax = 0);

COMMENT ON COLUMN billing_documents.opening_batch_id IS
  'Set on a flat''s opening due brought forward at cut-over. Such a document is a receivable carried in, not a supply: it has no GST and never appears in gst_register.';

ALTER TABLE vendor_bills
  ADD COLUMN opening_batch_id UUID REFERENCES opening_balance_batches(id);
ALTER TABLE vendor_bills ADD CONSTRAINT vendor_bills_opening_plain
  CHECK (opening_batch_id IS NULL OR (input_gst = 0 AND tds_amount = 0));

-- One flat's opening due is not cancelled on its own: that would reverse the
-- whole opening entry, which it points at. It is cancelled only as part of
-- reversing its batch.
CREATE OR REPLACE FUNCTION check_opening_document_state() RETURNS TRIGGER AS $$
DECLARE
  batch_state TEXT;
BEGIN
  IF OLD.opening_batch_id IS NULL OR NEW.state IS NOT DISTINCT FROM OLD.state THEN
    RETURN NEW;
  END IF;
  SELECT state INTO batch_state FROM opening_balance_batches WHERE id = OLD.opening_batch_id;
  IF NEW.state = 'cancelled' AND batch_state = 'reversed' THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION
    'document % is an opening balance brought forward, not a bill; correct it by reversing the opening balances and entering them again',
    OLD.proforma_no;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER billing_documents_opening_state
  BEFORE UPDATE OF state ON billing_documents
  FOR EACH ROW EXECUTE FUNCTION check_opening_document_state();

-- No GST row for an opening due, nor for a note adjusting one. Enforced here
-- because the register is what a return is filed from.
CREATE OR REPLACE FUNCTION check_gst_register_not_opening() RETURNS TRIGGER AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM billing_documents d
     WHERE d.opening_batch_id IS NOT NULL
       AND (d.id = NEW.document_id
            OR d.id = (SELECT a.document_id FROM invoice_adjustments a WHERE a.id = NEW.adjustment_id))
  ) THEN
    RAISE EXCEPTION
      'an opening balance brought forward is not a supply, so it has no GST and no place in the GST register';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER gst_register_not_opening
  BEFORE INSERT ON gst_register
  FOR EACH ROW EXECUTE FUNCTION check_gst_register_not_opening();

COMMIT;


